input.sparql:
SELECT ?zone ?zoneName ?sensor ?sensorClass ?tsId WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zoneName .
  FILTER(?zoneName IN ("Core_mid", "Perimeter_mid_ZN_3", "Perimeter_top_ZN_3"))
  ?sensor brick:isPointOf ?zone .
  ?sensor a ?sensorClass .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsId . }
}

SELECT ?zone ?sensor ?tsId WHERE {
  VALUES ?zone { 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01> 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> 
  }
  ?sensor brick:isPointOf ?zone .
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor ref:hasTimeseriesId ?tsId .
}

